import unittest
from candidate import triangle_area

class TestTriangleArea(unittest.TestCase):
    def test_triangle_area_normalcase_integers(self):
        self.assertEqual(triangle_area(5, 3), 7.5)

    def test_triangle_area_normalcase_floats(self):
        self.assertAlmostEqual(triangle_area(2.5, 4.0), 5.0)

    def test_triangle_area_boundary_zero_height(self):
        self.assertEqual(triangle_area(5, 0), 0.0)

    def test_triangle_area_boundary_zero_base(self):
        self.assertEqual(triangle_area(0, 3), 0.0)

    def test_triangle_area_boundary_both_zero(self):
        self.assertEqual(triangle_area(0, 0), 0.0)

    def test_triangle_area_docstring_example(self):
        self.assertEqual(triangle_area(5, 3), 7.5)

    def test_triangle_area_negative_values(self):
        self.assertEqual(triangle_area(-5, 3), -7.5)

    def test_triangle_area_none_value_raises_typeerror(self):
        with self.assertRaises(TypeError):
            triangle_area(None, 3)

    def test_triangle_area_string_value_raises_typeerror(self):
        with self.assertRaises(TypeError):
            triangle_area("5", 3)
